{
  "API_calls": [],
  "collected_information": {
    "pyproject.toml": {
      "python_version": ">=3.10,<3.14",
      "main_dependencies": [
        "langflow-base==0.1.1",
        "crewai~=0.86.0"
      ],
      "dev_dependencies": [
        "pytest >=8.2.0 with coverage"
      ],
      "test_command_example": "python -m pytest --ignore=tests/integration --cov --cov-report=term --cov-report=html --instafail -ra -n auto -m \"not api_key_required\"",
      "build_system": "hatchling"
    },
    "README.md": {
      "supported_python_versions": "3.10 to 3.12",
      "installation": [
        "uv pip install langflow",
        "pip install langflow"
      ],
      "documentation_links": "detailed external documentation"
    },
    "CONTRIBUTING.md": {
      "reference": "DEVELOPMENT.md for setup and test instructions"
    },
    "DEVELOPMENT.md": {
      "node_version": "v22.12 LTS",
      "npm_version": "v10.9",
      "python_package_manager": "uv >=0.4",
      "preferred_os": "macOS/Linux or WSL on Windows",
      "make_commands": {
        "init": "make init",
        "backend": "make backend",
        "frontend": "make frontend",
        "unit_tests": "make unit_tests"
      },
      "specific_test_run": "uv run pytest src/backend/tests/unit/<test_file>.py",
      "dev_container": "recommended",
      "pre_commit_hooks": "installation and usage described",
      "environment_variable_opt_out": "DO_NOT_TRACK=true"
    },
    ".env.example": {
      "environment_variables": "Database, caching, host, port, logging, auth, cache backends",
      "examples": ["sqlite/postgres for DB URLs"],
      "caching": "Redis supported",
      "advice": "copy to .env and do not commit"
    },
    ".github/workflows": {
      "contents": "python_test.yml and other CI test workflows exist; contents not extracted but not required"
    }
  },
  "terminate": true
}
